style.css:
@-moz-document domain("youtube.com") {
/* GLOW RIOT - RAINBOW PARTY LIGHTS */

@keyframes glow-riot-rainbow {
  0% {
    color: #ff0000;
    text-shadow: 0 0 8px #ff0000;
  }
  12.5% {
    color: #ff8000;
    text-shadow: 0 0 8px #ff8000;
  }
  25% {
    color: #ffff00;
    text-shadow: 0 0 8px #ffff00;
  }
  37.5% {
    color: #39ff14;
    text-shadow: 0 0 8px #39ff14;
  }
  50% {
    color: #00ffcc;
    text-shadow: 0 0 8px #00ffcc;
  }
  62.5% {
    color: #008cff;
    text-shadow: 0 0 8px #008cff;
  }
  75% {
    color: #a020f0;
    text-shadow: 0 0 8px #a020f0;
  }
  87.5% {
    color: #ff1493;
    text-shadow: 0 0 8px #ff1493;
  }
  100% {
    color: #ff0000;
    text-shadow: 0 0 8px #ff0000;
  }
}

/* VIDEO TITLES: HOME, RECOMMENDATIONS, PLAYLISTS AND QUEUES */

ytd-rich-grid-media #video-title,
ytd-rich-item-renderer #video-title,
ytd-playlist-panel-video-renderer #video-title,
ytd-compact-video-renderer #video-title,
ytd-video-renderer #video-title {
  font-family: "Cosmic Sans", "Comic Sans MS", cursive !important;
  font-weight: 900 !important;
  -webkit-text-fill-color: currentColor !important;
  animation: glow-riot-rainbow 8s steps(1, end) infinite !important;
}

/* CHANNEL NAMES ON WATCH PAGES */

ytd-channel-name #text,
#channel-name a,
#channel-name yt-formatted-string {
  animation: glow-riot-rainbow 8s steps(1, end) infinite !important;
  -webkit-text-fill-color: currentColor !important;
}
}
